import sys; sys.path.insert(0, sys.argv[1])
from adminhub import db, users, api, audit
from tests.conftest import SAMPLE_USERS
def fresh():
    c = db.connect(":memory:")
    for e,n,r,t in SAMPLE_USERS: users.create_user(c,e,n,r,t)
    return c
c=fresh()
print("pages per_page=2 (5 users):", api.list_users(c,{"per_page":"2"})["body"]["pages"])
print("pages per_page=10:", api.list_users(c,{"per_page":"10"})["body"]["pages"])
try: print(api.list_users(c,{"per_page":"0"}))
except Exception as e: print("per_page=0:", type(e).__name__, e)
try: print(api.list_users(c,{"page":"x"}))
except Exception as e: print("page=x:", type(e).__name__, e)
print("page=0:", [u["id"] for u in api.list_users(c,{"page":"0","per_page":"2"})["body"]["users"]])
print("per_page=-1:", len(api.list_users(c,{"per_page":"-1"})["body"]["users"]))
print("inject:", [u["email"] for u in api.search(c,{"q":"zzz' OR 1=1 --"})["body"]["users"]])
try: print(api.search(c,{"q":"o'brien"}))
except Exception as e: print("apostrophe:", type(e).__name__, e)
print("search has pages key:", "pages" in api.search(c,{"q":"example"})["body"])
# bulk with unknown ids
print("bulk unknown:", api.bulk_deactivate(c,{"ids":["1","99"],"actor":"root"}), c.execute("select target_id from audit_log").fetchall() and [r[0] for r in c.execute("select target_id from audit_log")])
try: api.bulk_deactivate(c,{"ids":["2"]})
except Exception as e: print("no actor:", type(e).__name__, e)
try: api.bulk_deactivate(c,{"ids":["abc"],"actor":"r"})
except Exception as e: print("bad id:", type(e).__name__, e)
# audit failure swallowed
c=fresh(); c.execute("drop table audit_log")
print("audit table missing ->", api.bulk_deactivate(c,{"ids":["1","2"],"actor":"root"}))
# existing DB without audit_log? connect runs IF NOT EXISTS -> fine
EOF
